  "id": "xls-01-p2",
  "prompt": "What is the current list price, in naira, of **Bottled water 75cl (12)**?",
  "answer": 4000,
  "format": "naira",
  "dataset": "sales",
  "files": ["products"],
  "verify": "SELECT list_price FROM products WHERE product_name = 'Bottled water 75cl (12)'",
