  "answer": 830541245,
  "tolerance": 1,
  "format": "naira",
  "dataset": "sales",
  "files": ["orders"],
  "verify": "SELECT SUM(quantity * unit_price * (1 - discount_pct / 100.0)) FROM orders",
  "hint": "Card visual → drag revenue in. To see the exact number, Format visual → Callout value → Display units: None.",
  "required": true
}
```

